using System;
using System.Globalization;
using System.Text.Json;
using System.Threading;
using System.Threading.Tasks;
using Parcs.Agent.Runtime;

public static class Fx {
    public const ulong M = 16777216UL;
    public const long K = 5000000L;
    public static long CountUpTo(double mid, int wi, int tw) {
        long c = 0;
        for (ulong i = (ulong)wi + 1; i <= M; i += (ulong)tw) {
            ulong z = unchecked(i * 0x9E3779B97F4A7C15UL);
            z = unchecked((z ^ (z >> 30)) * 0xBF58476D1CE4E5B9UL);
            z = unchecked((z ^ (z >> 27)) * 0x94D049BB133111EBUL);
            z = z ^ (z >> 31);
            ulong r = z % 2147483647UL;
            if ((double)r / 2147483647.0 <= mid) c++;
        }
        return c;
    }
}

public class Cnt {
    public double lo { get; set; }
    public double hi { get; set; }
    public long partial { get; set; }
}

public class Step1 : IAgentComputation {
    public Task<AgentLayerResult> ExecuteAsync(AgentLayerInput input, CancellationToken ct) {
        long c = Fx.CountUpTo(0.5, input.WorkerIndex, input.TotalWorkers);
        return Task.FromResult(AgentLayerResult.Ok(JsonSerializer.Serialize(new Cnt { lo = 0.0, hi = 1.0, partial = c })));
    }
}

public class Step2 : IAgentComputation {
    public Task<AgentLayerResult> ExecuteAsync(AgentLayerInput input, CancellationToken ct) {
        long total = 0; double lo = 0.0, hi = 1.0; bool any = false;
        foreach (var s in input.GetPreviousOutputs()) {
            if (s == null) continue;
            Cnt c = JsonSerializer.Deserialize<Cnt>(s);
            total += c.partial;
            if (!any) { lo = c.lo; hi = c.hi; any = true; }
        }
        double mid = (lo + hi) / 2.0;
        if (total >= Fx.K) hi = mid; else lo = mid;
        long cnt = Fx.CountUpTo((lo + hi) / 2.0, input.WorkerIndex, input.TotalWorkers);
        return Task.FromResult(AgentLayerResult.Ok(JsonSerializer.Serialize(new Cnt { lo = lo, hi = hi, partial = cnt })));
    }
}

public class Final : IAgentComputation {
    public Task<AgentLayerResult> ExecuteAsync(AgentLayerInput input, CancellationToken ct) {
        long total = 0; double lo = 0.0, hi = 1.0; bool any = false;
        foreach (var s in input.GetPreviousOutputs()) {
            if (s == null) continue;
            Cnt c = JsonSerializer.Deserialize<Cnt>(s);
            total += c.partial;
            if (!any) { lo = c.lo; hi = c.hi; any = true; }
        }
        double mid = (lo + hi) / 2.0;
        if (total >= Fx.K) hi = mid; else lo = mid;
        double fm = (lo + hi) / 2.0;
        return Task.FromResult(AgentLayerResult.Ok(JsonSerializer.Serialize(new {
            totalAtLastStep = total, lo = lo, hi = hi, finalMid = fm,
            finalMidG17 = fm.ToString("G17", CultureInfo.InvariantCulture) })));
    }
}
